CREATE TYPE public.app_role AS ENUM ('seeker','mentor','employer','admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK(length(display_name)<151), headline text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', skills text[] NOT NULL DEFAULT '{}', education text NOT NULL DEFAULT '', experience text NOT NULL DEFAULT '', interests text NOT NULL DEFAULT '', bio text NOT NULL DEFAULT '', created_at timestamptz DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'seeker');
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE POLICY roles_self ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profiles_self ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,LEFT(COALESCE(NEW.raw_user_meta_data->>'display_name',NEW.raw_user_meta_data->>'name',''),150)); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id, CASE WHEN NEW.raw_user_meta_data->>'role' IN ('mentor','employer') THEN (NEW.raw_user_meta_data->>'role')::public.app_role ELSE 'seeker'::public.app_role END); RETURN NEW; END $$;
CREATE TRIGGER on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.directory (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE, display_name text NOT NULL CHECK(length(display_name) BETWEEN 1 AND 150), headline text NOT NULL DEFAULT '', organization text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', skills text[] NOT NULL DEFAULT '{}', bio text NOT NULL DEFAULT '', kind text NOT NULL CHECK(kind IN ('mentor','employer','professional')), initials text NOT NULL DEFAULT '', available boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.directory TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.directory TO authenticated; GRANT ALL ON public.directory TO service_role;
ALTER TABLE public.directory ENABLE ROW LEVEL SECURITY;
CREATE POLICY directory_read ON public.directory FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY directory_write ON public.directory FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND ((kind='mentor' AND public.has_role(auth.uid(),'mentor')) OR (kind='employer' AND public.has_role(auth.uid(),'employer')) OR kind='professional'));
CREATE TABLE public.opportunities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid, title text NOT NULL CHECK(length(title) BETWEEN 3 AND 200), organization text NOT NULL CHECK(length(organization) BETWEEN 2 AND 150), location text NOT NULL, type text NOT NULL CHECK(type IN ('Internship','Fellowship','Entry-level job')), skills text[] NOT NULL DEFAULT '{}', description text NOT NULL CHECK(length(description) BETWEEN 10 AND 10000), deadline date NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','published','rejected')), created_at timestamptz DEFAULT now());
GRANT SELECT ON public.opportunities TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.opportunities TO authenticated; GRANT ALL ON public.opportunities TO service_role;
ALTER TABLE public.opportunities ENABLE ROW LEVEL SECURITY;
CREATE POLICY opportunities_read ON public.opportunities FOR SELECT TO anon,authenticated USING(status='published' OR owner_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY opportunities_create ON public.opportunities FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid() AND public.has_role(auth.uid(),'employer') AND status='pending');
CREATE POLICY opportunities_owner ON public.opportunities FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid() AND status='pending');
CREATE POLICY opportunities_admin ON public.opportunities FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, name text NOT NULL, path text NOT NULL, created_at timestamptz DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.documents TO authenticated; GRANT ALL ON public.documents TO service_role;
ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY documents_self ON public.documents FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND split_part(path,'/',1)=auth.uid()::text);
CREATE TABLE public.applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), opportunity_id uuid NOT NULL REFERENCES public.opportunities(id), applicant_id uuid NOT NULL REFERENCES public.profiles(id), cover_letter text NOT NULL CHECK(length(cover_letter) BETWEEN 10 AND 5000), document_id uuid REFERENCES public.documents(id), status text NOT NULL DEFAULT 'Submitted' CHECK(status IN ('Submitted','Shortlisted','Rejected','Accepted')), created_at timestamptz DEFAULT now(), UNIQUE(opportunity_id,applicant_id));
GRANT SELECT,INSERT,UPDATE ON public.applications TO authenticated; GRANT ALL ON public.applications TO service_role;
ALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY applications_read ON public.applications FOR SELECT TO authenticated USING(applicant_id=auth.uid() OR EXISTS(SELECT 1 FROM public.opportunities o WHERE o.id=opportunity_id AND o.owner_id=auth.uid()) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY applications_create ON public.applications FOR INSERT TO authenticated WITH CHECK(applicant_id=auth.uid() AND public.has_role(auth.uid(),'seeker') AND status='Submitted' AND EXISTS(SELECT 1 FROM public.opportunities o WHERE o.id=opportunity_id AND o.status='published' AND o.deadline>=CURRENT_DATE) AND (document_id IS NULL OR EXISTS(SELECT 1 FROM public.documents d WHERE d.id=document_id AND d.user_id=auth.uid())));
CREATE POLICY applications_review ON public.applications FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM public.opportunities o WHERE o.id=opportunity_id AND o.owner_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.opportunities o WHERE o.id=opportunity_id AND o.owner_id=auth.uid()));
CREATE POLICY applicant_profile ON public.profiles FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.applications a JOIN public.opportunities o ON o.id=a.opportunity_id WHERE a.applicant_id=profiles.id AND o.owner_id=auth.uid()));
CREATE POLICY employer_document ON public.documents FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.applications a JOIN public.opportunities o ON o.id=a.opportunity_id WHERE a.document_id=documents.id AND o.owner_id=auth.uid()));
CREATE TABLE public.mentorship_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), seeker_id uuid NOT NULL REFERENCES public.profiles(id), mentor_id uuid NOT NULL REFERENCES public.directory(id), message text NOT NULL CHECK(length(message) BETWEEN 10 AND 2000), status text NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Accepted','Declined')), created_at timestamptz DEFAULT now(), UNIQUE(seeker_id,mentor_id));
GRANT SELECT,INSERT,UPDATE ON public.mentorship_requests TO authenticated; GRANT ALL ON public.mentorship_requests TO service_role;
ALTER TABLE public.mentorship_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY mentorship_read ON public.mentorship_requests FOR SELECT TO authenticated USING(seeker_id=auth.uid() OR EXISTS(SELECT 1 FROM public.directory d WHERE d.id=mentor_id AND d.user_id=auth.uid()) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY mentorship_create ON public.mentorship_requests FOR INSERT TO authenticated WITH CHECK(seeker_id=auth.uid() AND public.has_role(auth.uid(),'seeker') AND status='Pending' AND EXISTS(SELECT 1 FROM public.directory d WHERE d.id=mentor_id AND d.kind='mentor' AND d.available AND d.user_id IS NOT NULL));
CREATE POLICY mentorship_review ON public.mentorship_requests FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM public.directory d WHERE d.id=mentor_id AND d.user_id=auth.uid()));
CREATE POLICY mentee_profile ON public.profiles FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.mentorship_requests r JOIN public.directory d ON d.id=r.mentor_id WHERE r.seeker_id=profiles.id AND d.user_id=auth.uid()));
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.mentorship_requests(id), sender_id uuid NOT NULL, body text NOT NULL CHECK(length(body) BETWEEN 1 AND 3000), created_at timestamptz DEFAULT now());
GRANT SELECT,INSERT ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_read ON public.messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.mentorship_requests r JOIN public.directory d ON d.id=r.mentor_id WHERE r.id=request_id AND r.status='Accepted' AND (r.seeker_id=auth.uid() OR d.user_id=auth.uid())));
CREATE POLICY messages_send ON public.messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND EXISTS(SELECT 1 FROM public.mentorship_requests r JOIN public.directory d ON d.id=r.mentor_id WHERE r.id=request_id AND r.status='Accepted' AND (r.seeker_id=auth.uid() OR d.user_id=auth.uid())));
CREATE TABLE public.connections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, directory_id uuid NOT NULL REFERENCES public.directory(id), UNIQUE(user_id,directory_id));
GRANT SELECT,INSERT,DELETE ON public.connections TO authenticated; GRANT ALL ON public.connections TO service_role;
ALTER TABLE public.connections ENABLE ROW LEVEL SECURITY;
CREATE POLICY connections_self ON public.connections FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE POLICY files_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='career-documents' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='career-documents' AND ((storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.documents d JOIN public.applications a ON a.document_id=d.id JOIN public.opportunities o ON o.id=a.opportunity_id WHERE d.path=name AND o.owner_id=auth.uid())));
CREATE POLICY files_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='career-documents' AND (storage.foldername(name))[1]=auth.uid()::text);
INSERT INTO public.opportunities(title,organization,location,type,skills,description,deadline,status) VALUES ('Junior Software Developer','Tech for Good','Nairobi, Kenya · Hybrid','Internship',ARRAY['JavaScript','React','Problem solving'],'Join our engineering team to build accessible digital tools for local communities. Work with experienced developers, contribute to real projects and receive structured career support. A foundational understanding of JavaScript and a willingness to learn are essential.','2027-02-28','published'),('Community Development Fellow','Community Futures','Kampala, Uganda · On-site','Fellowship',ARRAY['Communication','Project management'],'Support community-led programmes, coordinate events and develop your leadership skills through a paid six-month fellowship with dedicated mentorship.','2027-03-15','published'),('Marketing & Communications Assistant','Bright Horizons','Remote · East Africa','Entry-level job',ARRAY['Marketing','Writing','Social media'],'Help share stories of impact. Create engaging social content, support campaigns and work with our communications team. We welcome multilingual applicants and transferable experience.','2027-02-15','published'),('Data Analyst Intern','Open Impact','Nairobi, Kenya · Hybrid','Internship',ARRAY['Python','Excel','Data analysis'],'Turn community data into insights. Learn reporting and visualization alongside our analysts in a supportive three-month internship.','2027-03-30','published');
INSERT INTO public.directory(display_name,headline,organization,location,skills,bio,kind,initials) VALUES ('Sarah Mwangi','Senior Product Designer','Design for Change','Nairobi, Kenya',ARRAY['Design','Career planning'],'Helping emerging designers build confidence, portfolios and meaningful careers.','mentor','SM'),('Ahmed Khalil','Engineering Manager','Tech for Good','Kampala, Uganda',ARRAY['JavaScript','React','Engineering'],'Supporting software professionals as they navigate their first local role.','mentor','AK'),('Grace Okafor','People & Culture Lead','Community Futures','Remote',ARRAY['Interview preparation','Leadership'],'Connecting talent with opportunity through practical interview and career coaching.','mentor','GO');